[ru]
Act_II = "Истощение";
Act_II_01 =
"\cDТы внезапно обнаруживаешь себя в дрейфе между сном и бодрствованием. В этом пограничном состоянии трудно разобраться: и бодрствование, и бессознательность пытаются заявить права "
"на твою личную реальность.";
Act_II_02 =
"\cDУвы, похоже, на этот раз победило истощение. Тяжелеют не только веки, но и мышцы, рефлексы, даже мысли становятся тяжелее...\n\n"
"И прежде чем ты это осознаёшь — невесомость. В сопровождении глубокого расслабления, свободного от любого бремени, физического и умственного.";
Act_II_03 =
"\cDСкоро ты прибудешь. Приглашённый на перекрёсток. Мир, который не увидеть невооружённым глазом — только чистым, обнажённым умам.";
Bed_01a = "\cDВыглядит приглашающе... может, на этот раз «сны» будут лучше.";
Bed_01a_1 = "\cD[Спать]";
